Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>

#define mk make_pair
#define pushb push_back
#define ll long long

using namespace std;

const int MOD = 1000000007;

int parent_nodes[1111111];
int count_components;

int find_parent(int x) {
    if (x == parent_nodes[x]) return x;
    return parent_nodes[x] = find_parent(parent_nodes[x]);
}

void union_sets(int a, int b) {
    a = find_parent(a);
    b = find_parent(b);
    if (a == b) return;
    count_components--;
    parent_nodes[b] = a;
}

ll mod_exp(ll base, int exp) {
    if (exp == 0) return 1;
    ll half = mod_exp(base, exp / 2);
    ll res = (half * half) % MOD;
    if (exp & 1) res = (res * base) % MOD;
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << mod_exp(p, p - 1) << '\n';
        return 0;
    }

    count_components = p - (k > 1);
    for (ll i = 1; i < p; i++) parent_nodes[i] = i;

    for (ll i = 1; i < p; i++) {
        union_sets(i, (i * k) % p);
    }

    cout << mod_exp(p, count_components) << '\n';

    return 0;
}
</original_code>
